//! Scaffolding and architectural planning orchestration.

use crate::contract::discovery::inspect_project;
use std::fmt::Write;
use std::fs;
use std::path::{Path, PathBuf};

pub const TEST_HARNESS_TEMPLATE: &str = r#"//! SlugRails Architectural Integration Test Harness.
//!
//! Generated by SlugRails to lay down the rails so `cargo test` triggers enforcement.
//! Run with `cargo test --test slugrails` or standard `cargo test`.

use std::path::Path;
use std::process::Command;

#[test]
fn test_architecture_contract_enforced() {
    let manifest_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let arch_file = manifest_dir.join(".planning").join("ARCHITECTURE.md");

    if !arch_file.exists() {
        eprintln!(
            "SlugRails Notice: .planning/ARCHITECTURE.md not found. \
            Run 'slugrails init' or 'slugrails plan' to establish your architecture contract."
        );
        return;
    }

    // Trigger the rails via slugrails CLI if installed, or fallback to cargo run
    let output = Command::new("slugrails")
        .args(["check", "--all", "--root"])
        .arg(manifest_dir)
        .output()
        .or_else(|_| {
            Command::new("cargo")
                .args(["run", "--quiet", "--bin", "slugrails", "--", "check", "--all", "--root"])
                .arg(manifest_dir)
                .output()
        });

    match output {
        Ok(out) => {
            if !out.status.success() {
                let stdout = String::from_utf8_lossy(&out.stdout);
                let stderr = String::from_utf8_lossy(&out.stderr);
                panic!(
                    "\n═══════════════════════════════════════════════════════════════\n\
                     SLUGRAILS CONTRACT VIOLATION TRIGGERED VIA CARGO TEST\n\
                     ═══════════════════════════════════════════════════════════════\n\
                     {}\n{}\
                     ═══════════════════════════════════════════════════════════════\n\
                     Fix violations or authorize exceptions: slugrails exception add <file> <guard>\n",
                    stdout, stderr
                );
            }
        }
        Err(e) => {
            panic!("SlugRails Failure: could not execute 'slugrails' CLI to enforce rails: {e}");
        }
    }
}
"#;

/// Discovers domain architecture, validates parameters, and generates TOML contract.
///
/// # Errors
///
/// Returns an I/O error if creating directories or writing contract files fails.
pub fn plan_architecture(
    root: &Path,
    intent_desc: Option<&str>,
    style_hint: Option<&str>,
    custom_layers: Option<Vec<String>>,
    custom_rules: Option<Vec<String>>,
) -> std::io::Result<String> {
    let plan_dir = root.join(".planning");
    fs::create_dir_all(&plan_dir)?;

    let intent = intent_desc.unwrap_or("Define system boundaries and human intent here.");
    let inspection = inspect_project(root, intent, style_hint);

    let layers = custom_layers.unwrap_or(inspection.candidate_layers);
    let enforce = custom_rules.unwrap_or(inspection.recommended_rules);

    // Validate inputs against malicious characters (TOML injection defense)
    for layer in &layers {
        if !layer
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_' || c == '-')
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "Invalid layer name",
            ));
        }
    }
    for rule in &enforce {
        if !rule
            .chars()
            .all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '/')
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidInput,
                "Invalid rule name",
            ));
        }
    }

    let layers_str = layers
        .iter()
        .map(|l| format!("\"{l}\""))
        .collect::<Vec<_>>()
        .join(", ");
    let enforce_str = enforce
        .iter()
        .map(|e| format!("\"{e}\""))
        .collect::<Vec<_>>()
        .join(", ");

    let mut deps_str = String::new();
    for (k, v) in &inspection.allowed_dependencies {
        let targets = v
            .iter()
            .map(|t| format!("\"{t}\""))
            .collect::<Vec<_>>()
            .join(", ");
        let _ = writeln!(deps_str, "{k} = [{targets}]");
    }

    let arch_path = plan_dir.join("ARCHITECTURE.md");
    let arch_content = format!(
        "+++\n\
         layers = [{layers_str}]\n\
         enforce = [{enforce_str}]\n\n\
         [allowed_dependencies]\n\
         {deps_str}\
         +++\n\n\
         # Intent & Architectural Contract\n\n\
         {intent}\n"
    );
    fs::write(&arch_path, &arch_content)?;
    crate::storage::save_contract_baseline(root, &arch_content)?;

    let slugplan_dir = crate::util::get_project_plan_dir(root);
    fs::create_dir_all(&slugplan_dir)?;
    let intent_json_path = slugplan_dir.join("intent.json");
    let intent_data = serde_json::json!({
        "intent": intent,
        "style": style_hint.unwrap_or("discovered"),
        "detected_language": inspection.detected_language,
        "discovered_modules": inspection.existing_modules,
        "layers": layers,
        "enforced_guards": enforce,
        "created_by": "slugplan"
    });
    fs::write(
        &intent_json_path,
        serde_json::to_string_pretty(&intent_data)?,
    )?;

    let harness_path = scaffold_tests_harness(root)?;
    let _ = crate::library::ensure_test_library_seeded();

    Ok(format!(
        "SlugPlan successfully converged architectural intent:\n\
         - Language: {}\n\
         - Modules Found: {:?}\n\
         - Contract: {}\n\
         - Test Harness: {}\n\
         Run 'cargo test --test slugrails' or 'slugrails check' to enforce intent.",
        inspection.detected_language,
        inspection.existing_modules,
        arch_path.display(),
        harness_path.display()
    ))
}

/// Generates tests/slugrails.rs in the specified project directory.
///
/// # Errors
///
/// Returns an I/O error if creating directories or writing the harness fails.
pub fn scaffold_tests_harness(root: &Path) -> std::io::Result<PathBuf> {
    let tests_dir = root.join("tests");
    if !tests_dir.exists() {
        fs::create_dir_all(&tests_dir)?;
    }
    let target = tests_dir.join("slugrails.rs");
    fs::write(&target, TEST_HARNESS_TEMPLATE)?;
    Ok(target)
}
